namespace ghidra.app.plugin.core.debug.gui.breakpoint;









using docking.widgets.table;
using docking.widgets.table;
using ghidra.debug.api.breakpoint.LogicalBreakpoint;

public abstract class DebuggerBreakpointStateTableCellEditor<T> : AbstractCellEditor, TableCellEditor, ActionListener {
	protected JButton button = new JButton();

	private State value = State.NONE;
	private T row;

	private Class<T> cls;

	public DebuggerBreakpointStateTableCellEditor(Class<T> cls) {
		this.cls = cls;

		button.setHorizontalAlignment(SwingConstants.CENTER);
		button.setOpaque(true);
		button.setBorder(BorderFactory.createEmptyBorder());
		button.setUI(new BasicButtonUI());

		button.addActionListener(this);
	}

	/* @Override */
	public object getCellEditorValue() {
		return value;
	}

	/* @Override */
	public Component getTableCellEditorComponent(JTable table, object value, bool isSelected,
			int row, int column) {
		if (!(table is GTable gtable)) {
			return null;
		}
		GTableFilterPanel<object> filterPanel = gtable.getTableFilterPanel();
		if (isSelected) {
			button.setBackground(table.getSelectionBackground());
		}
		else {
			// TODO: Alternating colors? Can't inherit GTableCellRenderer....
			button.setBackground(table.getBackground());
		}
		object rowObj = filterPanel.getRowObject(row);
		if (!(cls.isInstance(rowObj))) {
			return null;
		}

		this.row = cls.cast(rowObj);
		this.value = (State) value;
		button.setIcon(this.value.icon);
		button.setHorizontalAlignment(SwingConstants.CENTER);
		return button;
	}

	/* @Override */
	public void actionPerformed(ActionEvent e) {
		value = getToggledState(row, value);
		fireEditingStopped();
	}

	protected abstract State getToggledState(T row, State current);
}
